//! Parity against vectors generated by the Python implementation
//! (`hub_api/services/bundle_signing_service.py`); regenerate with the same code.
#![allow(clippy::unwrap_used, clippy::expect_used)]

use serde::Deserialize;
use waddles_ops_cli::signing::*;

#[derive(Deserialize)]
struct Vector {
    seed_b64: String,
    pub_b64: String,
    app_id: String,
    version: String,
    digest: String,
    approval_id: i64,
    payload_hex: String,
    sidecar: String,
}

fn vectors() -> Vec<Vector> {
    serde_json::from_str(include_str!("python_vectors.json")).unwrap()
}

fn hex(b: &[u8]) -> String {
    b.iter().map(|x| format!("{x:02x}")).collect()
}

#[test]
fn payload_and_sidecar_bytes_match_python() {
    let vs = vectors();
    assert_eq!(vs.len(), 3, "zero/short denominator");
    for v in &vs {
        let p = build_signing_payload(&v.app_id, &v.version, &v.digest, v.approval_id).unwrap();
        assert_eq!(hex(&p), v.payload_hex);
        let s = PlatformSigner::new(&v.seed_b64, "k1").unwrap();
        assert_eq!(s.public_key_b64(), v.pub_b64);
        let doc = s
            .sign(&v.app_id, &v.version, &v.digest, v.approval_id)
            .unwrap();
        // Ed25519 is deterministic: same key + payload => identical signature bytes.
        assert_eq!(doc.to_canonical_json().unwrap(), v.sidecar);
    }
}

#[test]
fn python_sidecars_verify_in_rust() {
    for v in vectors() {
        let keys = parse_public_keys(&format!("{{\"k1\":\"{}\"}}", v.pub_b64)).unwrap();
        verify_sidecar(v.sidecar.as_bytes(), &keys).unwrap();
    }
}

#[test]
fn tampering_and_bad_inputs_fail_closed() {
    let v = &vectors()[0];
    let keys = parse_public_keys(&format!("{{\"k1\":\"{}\"}}", v.pub_b64)).unwrap();
    let tampered = v
        .sidecar
        .replace("\"approval_id\":42", "\"approval_id\":43");
    assert_ne!(tampered, v.sidecar);
    assert!(verify_sidecar(tampered.as_bytes(), &keys).is_err());
    assert!(verify_sidecar(v.sidecar.as_bytes(), &Default::default()).is_err());
    assert!(build_signing_payload("a b", "1", "d", 1).is_err());
    assert!(build_signing_payload("", "1", "d", 1).is_err());
    assert!(build_signing_payload("a", "1", "d", -1).is_err());
    assert!(PlatformSigner::new("", "k").is_err());
    assert!(PlatformSigner::new("AAAA", "k").is_err());
    assert!(PlatformSigner::new("!!!", "k").is_err());
}
